import { test, expect, type Page } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

async function ensureWorkspace(page: Page): Promise<void> {
  const noWs = await page.getByText('No workspaces yet').isVisible({ timeout: 4_000 }).catch(() => false);
  if (noWs) {
    await page.getByRole('button', { name: 'Create workspace' }).first().click();
    await page.getByRole('dialog').getByRole('button', { name: 'Create workspace' }).click();
    await expect(page.getByText('Incident Dashboard')).toBeVisible({ timeout: 15_000 });
  }
}

async function reportAndOpenIncident(page: Page, title: string): Promise<void> {
  await page.getByRole('button', { name: '\u26a1 Report Incident' }).click();
  await page.getByRole('button', { name: 'P1' }).click();
  await page.getByPlaceholder('Brief incident title\u2026').fill(title);
  await page.getByPlaceholder('What is happening? Impact? Timeline?').fill('Timeline test incident');
  await page.getByRole('button', { name: 'Report Incident' }).click();
  await expect(page.getByText(title)).toBeVisible({ timeout: 10_000 });
  await page.getByText(title).first().click();
}

test.describe(`incident commander: post timeline updates during an incident`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await ensureWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after the commander posts a timeline entry, every team member viewing the incident sees the new entry within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();

    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);
      await ensureWorkspace(pageA);

      // Invite node 1 if needed
      const noWsB = await pageB.getByText('No workspaces yet').isVisible({ timeout: 4_000 }).catch(() => false);
      if (noWsB) {
        await pageA.getByRole('button', { name: '+ Invite' }).click();
        await pageA.getByRole('button', { name: 'Generate invite code' }).click();
        await expect(pageA.locator('label', { hasText: 'Invite code' })).toBeVisible({ timeout: 10_000 });
        const code = await pageA.locator('textarea').last().inputValue();
        await pageA.keyboard.press('Escape');
        await pageB.getByRole('button', { name: 'Join with invitation' }).click();
        await pageB.getByPlaceholder('Paste your invite code\u2026').fill(code);
        await pageB.getByRole('button', { name: 'Join workspace' }).click();
        await expect(pageB.getByText('Incident Dashboard')).toBeVisible({ timeout: 15_000 });
      }

      const title = 'E2E-Timeline-CrossNode';
      const entryBody = 'Restarted pooler — connections recovering';

      // Node 0: report incident and navigate to detail
      await reportAndOpenIncident(pageA, title);

      // Node 1: navigate to the same incident detail
      await expect(pageB.getByText(title)).toBeVisible({ timeout: 5_000 });
      await pageB.getByText(title).first().click();

      // Node 0: post a timeline entry
      await pageA.getByPlaceholder('Post a timeline update\u2026').fill(entryBody);
      await pageA.getByRole('button', { name: 'Post' }).click();

      // Node 1: entry is visible within 5 s
      await expect(pageB.getByText(entryBody)).toBeVisible({ timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });

  test(`timeline entries are ordered chronologically and show who posted them`, async ({ page }) => {
    const title = 'E2E-Timeline-Order';

    await reportAndOpenIncident(page, title);

    const entry1 = 'First update: investigating root cause';
    const entry2 = 'Second update: fix deployed to staging';

    // Post first entry
    await page.getByPlaceholder('Post a timeline update\u2026').fill(entry1);
    await page.getByRole('button', { name: 'Post' }).click();
    await expect(page.getByText(entry1)).toBeVisible({ timeout: 10_000 });

    // Post second entry
    await page.getByPlaceholder('Post a timeline update\u2026').fill(entry2);
    await page.getByRole('button', { name: 'Post' }).click();
    await expect(page.getByText(entry2)).toBeVisible({ timeout: 10_000 });

    // Both entries appear and the first precedes the second in DOM order
    const allBodies = page.locator('.tl-body, [class*="TLBody"]');
    // Fallback: check entry1 appears before entry2 by their bounding boxes
    const box1 = await page.getByText(entry1).first().boundingBox();
    const box2 = await page.getByText(entry2).first().boundingBox();
    if (box1 && box2) {
      expect(box1.y).toBeLessThan(box2.y);
    }

    // Timeline entries show who posted them (TLMeta contains author + entry_type)
    await expect(page.getByText('note')).toBeVisible({ timeout: 5_000 });
  });
});
